        if not word_set: return False
        dp = [False] * (len(word) + 1)
        dp[0] = True
        for i in range(1, len(word) + 1):
            for j in range(i):
                if dp[j] and word[j:i] in word_set:
                    dp[i] = True
                    break
        return dp[len(word)]
    for word in words:
        if can_form(word): res.append(word)
        word_set.add(word)
    return res

function alienOrder(words) {
