public class Solution {
    public static int shortestPathAllKeys(String[] grid) {
        int m = grid.length, n = grid[0].length();
        int startR = 0, startC = 0, keyCount = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                char ch = grid[r].charAt(c);
                if (ch == '@') { startR = r; startC = c; }
                else if (ch >= 'a' && ch <= 'f') keyCount++;
            }
        }
        int targetMask = (1 << keyCount) - 1;
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{startR, startC, 0, 0});
        boolean[][][] visited = new boolean[m][n][1 << keyCount];
        visited[startR][startC][0] = true;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0], c = curr[1], mask = curr[2], steps = curr[3];
            if (mask == targetMask) return steps;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nc < 0 || nr >= m || nc >= n || grid[nr].charAt(nc) == '#') continue;
                char ch = grid[nr].charAt(nc);
                int newMask = mask;
                if (ch >= 'a' && ch <= 'f') newMask |= (1 << (ch - 'a'));
                if (ch >= 'A' && ch <= 'F' && (mask & (1 << (ch - 'A'))) == 0) continue;
                if (!visited[nr][nc][newMask]) {
                    visited[nr][nc][newMask] = true;
                    queue.add(new int[]{nr, nc, newMask, steps + 1});
                }
            }
        }
        return -1;
    }
}

function trapRainWater(heightMap) {
  const m = heightMap.length, n = heightMap[0].length;
  if (m < 3 || n < 3) return 0;
  const visited = Array.from({ length: m }, () => new Array(n).fill(false));
  const heap = []; // Simulated Min-heap array
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (r === 0 || r === m - 1 || c === 0 || c === n - 1) {
        visited[r][c] = true;
        heap.push([heightMap[r][c], r, c]);
      }
    }
  }
  heap.sort((a, b) => a[0] - b[0]);
  let water = 0, maxBoundary = 0;
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  while (heap.length) {
    const [h, r, c] = heap.shift();
    maxBoundary = Math.max(maxBoundary, h);
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < m && nc < n && !visited[nr][nc]) {
        visited[nr][nc] = true;
        if (heightMap[nr][nc] < maxBoundary) water += maxBoundary - heightMap[nr][nc];
        heap.push([heightMap[nr][nc], nr, nc]);
        heap.sort((a, b) => a[0] - b[0]);
      }
    }
  }
  return water;
}

