class LFUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.minFreq = 0;
    this.keyMap = new Map();
    this.freqMap = new Map();
  }
  _update(node) {
    const oldFreq = node.freq;
    const oldList = this.freqMap.get(oldFreq);
    oldList.delete(node);
    if (oldFreq === this.minFreq && oldList.size === 0) this.minFreq++;
    node.freq++;
    if (!this.freqMap.has(node.freq)) this.freqMap.set(node.freq, new Set());
    this.freqMap.get(node.freq).add(node);
  }
  get(key) {
    if (!this.keyMap.has(key)) return -1;
    const node = this.keyMap.get(key);
    this._update(node);
    return node.val;
  }
  put(key, value) {
    if (this.capacity === 0) return;
    if (this.keyMap.has(key)) {
      const node = this.keyMap.get(key);
      node.val = value;
      this._update(node);
    } else {
      if (this.keyMap.size >= this.capacity) {
        const minList = this.freqMap.get(this.minFreq);
        const evictNode = minList.values().next().value;
        minList.delete(evictNode);
        this.keyMap.delete(evictNode.key);
      }
      const newNode = { key, val: value, freq: 1 };
      this.keyMap.set(key, newNode);
      this.minFreq = 1;
      if (!this.freqMap.has(1)) this.freqMap.set(1, new Set());
      this.freqMap.get(1).add(newNode);
    }
  }
}

type LFUNode = { key: number; val: number; freq: number };

class LFUCache {
  private capacity: number;
  private minFreq: number = 0;
  private keyMap = new Map<number, LFUNode>();
  private freqMap = new Map<number, Set<LFUNode>>();
  constructor(capacity: number) {
    this.capacity = capacity;
  }
  private _update(node: LFUNode) {
    const oldFreq = node.freq;
    const oldList = this.freqMap.get(oldFreq)!;
    oldList.delete(node);
    if (oldFreq === this.minFreq && oldList.size === 0) this.minFreq++;
    node.freq++;
    if (!this.freqMap.has(node.freq)) this.freqMap.set(node.freq, new Set());
    this.freqMap.get(node.freq)!.add(node);
  }
  get(key: number): number {
    if (!this.keyMap.has(key)) return -1;
    const node = this.keyMap.get(key)!;
    this._update(node);
    return node.val;
  }
  put(key: number, value: number): void {
    if (this.capacity === 0) return;
    if (this.keyMap.has(key)) {
      const node = this.keyMap.get(key)!;
      node.val = value;
      this._update(node);
    } else {
      if (this.keyMap.size >= this.capacity) {
        const minList = this.freqMap.get(this.minFreq)!;
        const evictNode = minList.values().next().value;
        minList.delete(evictNode);
        this.keyMap.delete(evictNode.key);
      }
      const newNode: LFUNode = { key, val: value, freq: 1 };
      this.keyMap.set(key, newNode);
      this.minFreq = 1;
      if (!this.freqMap.has(1)) this.freqMap.set(1, new Set());
      this.freqMap.get(1)!.add(newNode);
    }
  }
}

import java.util.*;

public class LFUCache {
    class Node {
        int key, val, freq;
        Node(int key, int val) { this.key = key; this.val = val; this.freq = 1; }
    }
    private final int capacity;
    private int minFreq = 0;
    private Map<Integer, Node> keyMap = new HashMap<>();
    private Map<Integer, LinkedHashSet<Node>> freqMap = new HashMap<>();
    public LFUCache(int capacity) { this.capacity = capacity; }
    public int get(int key) {
        if (!keyMap.containsKey(key)) return -1;
        Node node = keyMap.get(key);
        update(node);
        return node.val;
    }
    private void update(Node node) {
        int oldFreq = node.freq;
        LinkedHashSet<Node> oldList = freqMap.get(oldFreq);
        oldList.remove(node);
        if (oldFreq == minFreq && oldList.isEmpty()) minFreq++;
        node.freq++;
        freqMap.putIfAbsent(node.freq, new LinkedHashSet<>());
        freqMap.get(node.freq).add(node);
    }
    public void put(int key, int value) {
        if (capacity == 0) return;
        if (keyMap.containsKey(key)) {
            Node node = keyMap.get(key);
            node.val = value;
            update(node);
        } else {
            if (keyMap.size() >= capacity) {
                LinkedHashSet<Node> minList = freqMap.get(minFreq);
                Node evict = minList.iterator().next();
                minList.remove(evict);
                keyMap.remove(evict.key);
            }
            Node newNode = new Node(key, value);
            keyMap.put(key, newNode);
            minFreq = 1;
            freqMap.putIfAbsent(1, new LinkedHashSet<>());
            freqMap.get(1).add(newNode);
        }
    }
}

function findWords(board, words) {
  const root = {};
  for (const w of words) {
    let node = root;
    for (const c of w) {
      if (!node[c]) node[c] = {};
      node = node[c];
    }
    node.word = w;
  }
  const res = [];
  const m = board.length, n = board[0].length;
  function dfs(r, c, node) {
    const ch = board[r][c];
    if (!node[ch]) return;
    node = node[ch];
    if (node.word) {
      res.push(node.word);
      node.word = null;
    }
    board[r][c] = '#';
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < m && nc < n && board[nr][nc] !== '#') {
        dfs(nr, nc, node);
      }
    }
    board[r][c] = ch;
  }
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      dfs(r, c, root);
    }
  }
  return res;
}

interface TrieNode {
  children: Record<string, TrieNode>;
  word: string | null;
}

function findWords(board: string[][], words: string[]): string[] {
  const root: TrieNode = { children: {}, word: null };
  for (const w of words) {
    let node = root;
    for (const c of w) {
      if (!node.children[c]) node.children[c] = { children: {}, word: null };
      node = node.children[c];
    }
    node.word = w;
  }
  const res: string[] = [];
  const m = board.length, n = board[0].length;
  function dfs(r: number, c: number, node: TrieNode) {
    const ch = board[r][c];
    if (!node.children[ch]) return;
    node = node.children[ch];
    if (node.word) {
      res.push(node.word);
      node.word = null;
    }
    board[r][c] = '#';
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < m && nc < n && board[nr][nc] !== '#') {
        dfs(nr, nc, node);
      }
    }
    board[r][c] = ch;
  }
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      dfs(r, c, root);
    }
  }
  return res;
}

import java.util.*;

public class Solution {
    class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        String word = null;
    }
    public List<String> findWords(char[][] board, String[] words) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode node = root;
            for (char c : w.toCharArray()) {
                node.children.putIfAbsent(c, new TrieNode());
                node = node.children.get(c);
            }
            node.word = w;
        }
        List<String> res = new ArrayList<>();
        int m = board.length, n = board[0].length;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                dfs(board, r, c, root, res);
            }
        }
        return res;
    }
    private void dfs(char[][] board, int r, int c, TrieNode node, List<String> res) {
        char ch = board[r][c];
        if (!node.children.containsKey(ch)) return;
        node = node.children.get(ch);
        if (node.word != null) {
            res.add(node.word);
            node.word = null;
        }
        board[r][c] = '#';
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nc >= 0 && nr < board.length && nc < board[0].length && board[nr][nc] != '#') {
                dfs(board, nr, nc, node, res);
            }
        }
        board[r][c] = ch;
    }
}

def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    trie = {}
    for w in words:
        node = trie
        for c in w:
            node = node.setdefault(c, {})
        node['$'] = w
    m, n = len(board), len(board[0])
    res = []
    def dfs(r, c, parent):
        ch = board[r][c]
        curr = parent[ch]
        if '$' in curr:
            res.append(curr['$'])
            del curr['$']
        board[r][c] = '#'
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] in curr:
                dfs(nr, nc, curr)
        board[r][c] = ch
    for r in range(m):
        for c in range(n):
            if board[r][c] in trie:
                dfs(r, c, trie)
    return res

class NumArray {
  constructor(nums) {
    this.n = nums.length;
    this.nums = [...nums];
    this.tree = new Array(this.n + 1).fill(0);
    for (let i = 0; i < this.n; i++) {
      this._initAdd(i + 1, nums[i]);
    }
  }
  _initAdd(i, val) {
    while (i <= this.n) {
      this.tree[i] += val;
      i += i & (-i);
    }
  }
  update(index, val) {
    const delta = val - this.nums[index];
    this.nums[index] = val;
    let i = index + 1;
    while (i <= this.n) {
      this.tree[i] += delta;
      i += i & (-i);
    }
  }
  _prefixSum(i) {
    let sum = 0;
    while (i > 0) {
      sum += this.tree[i];
      i -= i & (-i);
    }
    return sum;
  }
  sumRange(left, right) {
    return this._prefixSum(right + 1) - this._prefixSum(left);
  }
}

