      heights.push(-h);
    } else {
      const idx = heights.indexOf(h);
      if (idx !== -1) heights.splice(idx, 1);
    }
    heights.sort((a, b) => b - a);
    const currentMax = heights[0];
    if (currentMax !== prevMax) {
      res.push([x, currentMax]);
      prevMax = currentMax;
    }
  }
  return res;
}

import java.util.*;

public class Solution {
    public static List<List<Integer>> getSkyline(int[][] buildings) {
        List<int[]> events = new ArrayList<>();
        for (int[] b : buildings) {
            events.add(new int[]{b[0], -b[2]});
            events.add(new int[]{b[1], b[2]});
        }
        Collections.sort(events, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        maxHeap.add(0);
        List<List<Integer>> res = new ArrayList<>();
        int prevMax = 0;
        for (int[] e : events) {
            int x = e[0], h = e[1];
            if (h < 0) {
                maxHeap.add(-h);
            } else {
                maxHeap.remove(h);
            }
            int currentMax = maxHeap.peek();
            if (currentMax != prevMax) {
                res.add(Arrays.asList(x, currentMax));
                prevMax = currentMax;
            }
        }
        return res;
    }
}
